const upsertJournalByUID = `-- name: UpsertJournalByUID :one
INSERT INTO journals (
    uid, calendar_id, summary, description,
    start_date, status, class, url,
    recurrence_rule, timezone, sequence, exdates, rdates, recurrence_id, dtstamp
) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(uid, recurrence_id) DO UPDATE SET
    calendar_id = excluded.calendar_id,
    summary = excluded.summary, description = excluded.description,
    start_date = excluded.start_date,
    status = excluded.status,
    class = excluded.class, url = excluded.url,
    recurrence_rule = excluded.recurrence_rule,
    timezone = excluded.timezone,
    sequence = MAX(excluded.sequence, journals.sequence + 1),
    exdates = excluded.exdates, rdates = excluded.rdates,
    dtstamp = excluded.dtstamp,
    deleted_at = NULL,
    updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
RETURNING id, uid, calendar_id, summary, description, start_date, status, class, url, recurrence_rule, timezone, sequence, exdates, rdates, recurrence_id, dtstamp, created_at, updated_at, deleted_at
`

type UpsertJournalByUIDParams struct {
	Uid            string
	CalendarID     int64
	Summary        string
	Description    *string
	StartDate      *string
	Status         string
	Class          string
	Url            *string
	RecurrenceRule *string
	Timezone       *string
	Sequence       int64
	Exdates        *string
	Rdates         *string
	RecurrenceID   string
	Dtstamp        *string
}

// NOTE: ON CONFLICT UPDATE clears deleted_at. This query resurrects
// soft-deleted rows. Callers outside the pull path in the sync engine
// must know this. The pull path is safe. The engine excludes
// tombstoned UIDs before this query runs (engine.go loads tombstones
// first and skips them during pull).
func (q *Queries) UpsertJournalByUID(ctx context.Context, arg UpsertJournalByUIDParams) (Journal, error) {
	row := q.db.QueryRowContext(ctx, upsertJournalByUID,
		arg.Uid,
		arg.CalendarID,
		arg.Summary,
		arg.Description,
		arg.StartDate,
		arg.Status,
		arg.Class,
		arg.Url,
		arg.RecurrenceRule,
		arg.Timezone,
		arg.Sequence,
		arg.Exdates,
		arg.Rdates,
		arg.RecurrenceID,
		arg.Dtstamp,
	)
	var i Journal
	err := row.Scan(
		&i.ID,
		&i.Uid,
		&i.CalendarID,
		&i.Summary,
		&i.Description,
		&i.StartDate,
		&i.Status,
		&i.Class,
		&i.Url,
		&i.RecurrenceRule,
		&i.Timezone,
		&i.Sequence,
		&i.Exdates,
		&i.Rdates,
		&i.RecurrenceID,
		&i.Dtstamp,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
